select.where:
del_flag = '0'

    and file_upload_manager_id = #{fileUploadManagerId}


    and review_name like concat('%', #{reviewName}, '%')


    and review_start_time >= #{reviewStartTime}


    and review_end_time <= #{reviewEndTime}


    and review_desc like concat('%', #{reviewDesc}, '%')


    and review_group_id like concat('%', #{reviewGroupId}, '%')


    and distribute_status = #{distributeStatus}

mapper.select:
select fur.id as file_upload_manager_id, fur.user_id,fur.file_task_name as review_name, (select real_name from auth_info where user_id = fur.user_id AND auth_status = '5' order by auth_time desc limit 1) user_name, fur.leader_teacher_id,fur.file_info, (select real_name from auth_info where user_id = fur.leader_teacher_id AND auth_status = '5' order by auth_time desc limit 1) as leader_teacher_name, fur.team_code, fur.team_name, cai.competition_series_id, cai.competition_name,fur.competition_stage_id, fur.competition_stage_name, cai.competition_track_name, cai.competition_track_id as competition_track_code, cai.second_level_code, cai.second_level_name,cai.school as school_id, rti.review_id, rti.review_start_time, rti.review_end_time, rti.review_desc, rti.review_group_id, rti.reference_document, rti.create_by, rti.create_time, rti.update_by, rti.update_time, rti.version, rti.del_flag,rti.distribute_status
from file_upload_manager fur left join review_task_info rti on fur.id = rti.file_upload_manager_id and rti.del_flag = '0'
left join competition_apply_info cai on fur.user_id = cai.user_id and fur.team_code = cai.team_code
and fur.del_flag = '0' and cai.competition_role_name = '队长'
and rti.review_name like concat('%', #{reviewName}, '%')
and cai.competition_series_id = #{competitionSeriesId}
and cai.competition_name like concat('%', #{competitionName}, '%')
and cai.competition_track_name like concat('%', #{competitionTrackName}, '%')
and cai.competition_track_id = #{competitionTrackCode}
and cai.second_level_code = #{secondLevelCode}
and cai.second_level_name like concat('%', #{secondLevelName}, '%')
and (cai.second_level_name like concat('%', #{competitionTrackQuery}, '%') or cai.competition_track_name like concat('%', #{competitionTrackQuery}, '%'))
and cai.school in (select id from nationwide_college_info where province in
#{item}
)
and rti.review_id in (select review_id from review_task_allot_group_relation where review_group_id = #{taskGroupId})
and (fur.leader_teacher_id in (select user_id from auth_info where real_name like concat('%', #{keyWords}, '%')) or fur.user_id in (select user_id from auth_info where real_name like concat('%', #{keyWords}, '%')) or cai.school in (select id from nationwide_college_info where school_name like concat('%', #{keyWords}, '%')))
and rti.distribute_status = #{distributeStatus}

mapper.update:
update review_task_info
file_upload_manager_id = #{fileUploadManagerId}, review_name = #{reviewName}, review_start_time = #{reviewStartTime}, review_end_time = #{reviewEndTime}, review_desc = #{reviewDesc}, review_group_id = #{reviewGroupId}, reference_document = #{referenceDocument}, distribute_status = #{distributeStatus}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, version = #{version}, del_flag = #{delFlag},
where review_id = #{reviewId}
